import React, { useState } from "react";
import passwordImg from "../assets/password.png";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";

export default function Login(props) {
  const [userId, setUserId] = useState("");
  const [password, setPassword] = useState("");
  const navigate = useNavigate();
  const { login } = useAuth();

  const API = import.meta.env.VITE_API_BASE_URL;

  const handleLogin = async (e) => {
    e.preventDefault();

    if (!userId || !password) {
      props.showAlert("Please fill in all fields", "warning");
      return;
    }

    try {
      const response = await fetch(`${API}/auth/login`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          user_id: userId,
          password: password,
        }),
      });

      const result = await response.json();

      if (!response.ok) {
        props.showAlert(result.error || "Login failed", "danger");
        return;
      }

      if (result.success) {
        const token = result.access_token;
        const user = result.user;

        login(user, token);

        props.showAlert("Login successful!", "success");
        navigate("/");
      } else {
        props.showAlert(result.error || "Invalid credentials", "danger");
      }
    } catch (error) {
      console.error("Login error:", error);
      props.showAlert("Server connection error", "danger");
    }
  };

  return (
    <div style={{ minHeight: "100vh", paddingTop: "80px" }}>
      <div className="container d-flex justify-content-center align-items-center min-vh-100">
        <div
          className="glass-container-light p-4 rounded-3 shadow-lg"
          style={{ width: "90%", maxWidth: "1000px" }}
        >
          <div className="row g-0">

            {/* Left Section */}
            <div className="col-lg-6 p-4 d-flex flex-column justify-content-center align-items-center">
              <h1 className="mb-4 text-center">Welcome Back</h1>
              <p className="mb-4 text-center">
                Log in to manage your scholarship applications and track status.
              </p>
              <img
                src="https://cdn-icons-png.flaticon.com/512/3135/3135715.png"
                alt="Illustration"
                className="img-fluid"
                style={{ maxHeight: "180px", opacity: 0.95 }}
              />
            </div>

            {/* Right Section */}
            <div className="col-lg-6 p-4">
              <form onSubmit={handleLogin}>
                <h2 className="mb-4 text-center">Login</h2>

                <div className="mb-3">
                  <label className="form-label">ID / Roll Number</label>
                  <input
                    type="text"
                    className="form-control"
                    placeholder="Enter your ID"
                    value={userId}
                    onChange={(e) => setUserId(e.target.value)}
                    required
                  />
                </div>

                <div className="mb-3">
                  <label className="form-label">Password</label>
                  <div className="input-group">
                    <span className="input-group-text">
                      <img src={passwordImg} alt="password" width="15" />
                    </span>
                    <input
                      type="password"
                      className="form-control"
                      placeholder="••••••••"
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      required
                    />
                  </div>
                </div>

                <button
                  type="submit"
                  className="btn w-100 py-2"
                  style={{
                    background: "linear-gradient(135deg, #ff3a3a 0%, #ff6b6b 100%)",
                    border: "none",
                    fontWeight: "600",
                    color: "white",
                  }}
                >
                  Login
                </button>

                <div className="text-center mt-3">
                  <Link to="/signup" style={{ textDecoration: "none" }}>
                    Don't have an account? Sign up
                  </Link>
                </div>
              </form>
            </div>

          </div>
        </div>
      </div>
    </div>
  );
}
